using System.Security.Cryptography; using System.Text; using Microsoft.Extensions.Options; namespace Backend.Api.Auth; public sealed class SessionService(IOptions<SessionOptions> options) { private readonly SessionOptions _options = options.Value; public bool ValidateCredentials(string username,string password)=>Fixed(username,_options.Username)&&Fixed(password,_options.Password); public string Create(string username,DateTimeOffset now){var expires=now.AddMinutes(_options.ExpirationMinutes).ToUnixTimeSeconds();var payload=$"{username}|{expires}";return $"{payload}|{Sign(payload)}";} public bool Validate(string? value,DateTimeOffset now,out string? username){username=null;if(string.IsNullOrWhiteSpace(value))return false;var p=value.Split('|');if(p.Length!=3||!long.TryParse(p[1],out var exp)||exp<=now.ToUnixTimeSeconds())return false;if(string.IsNullOrWhiteSpace(p[0])||!Fixed(p[2],Sign($"{p[0]}|{p[1]}")))return false;username=p[0];return true;} private string Sign(string value)=>Convert.ToBase64String(HMACSHA256.HashData(Encoding.UTF8.GetBytes(_options.SigningKey),Encoding.UTF8.GetBytes(value))); private static bool Fixed(string a,string b)=>CryptographicOperations.FixedTimeEquals(Encoding.UTF8.GetBytes(a),Encoding.UTF8.GetBytes(b)); }